<template>
  <div v-if="canManage" class="mobile-nav-item mobile-nav-inventory pointer-events-none absolute bottom-3 left-[22rem] z-[1540]">
    <button v-if="!open" type="button" class="mobile-nav-button pointer-events-auto rounded-2xl border border-emerald-300/25 bg-slate-950/90 px-3 py-2 text-xs font-black text-emerald-100 shadow-xl" @click="openPanel"><span class="mobile-nav-icon hidden">▦</span><span>Inventory</span></button>
    <section v-else class="pointer-events-auto fixed inset-2 flex flex-col overflow-hidden rounded-3xl border border-emerald-300/20 bg-slate-950/98 text-white shadow-2xl sm:inset-5">
      <header class="flex items-center gap-2 border-b border-white/10 px-4 py-3 sm:px-6"><div class="min-w-0 flex-1"><span class="text-[10px] font-black uppercase tracking-wider text-emerald-300">Stock management</span><h2 class="m-0 truncate text-lg font-black">Boat inventory</h2></div><button v-if="isAdmin" type="button" class="rounded-xl px-3 py-2 text-xs font-bold" :class="showSettings?'bg-sky-500 text-white':'bg-white/10 text-slate-200'" @click="showSettings=!showSettings">⚙ Settings</button><button type="button" class="rounded-xl bg-white/10 px-3 py-2" @click="open=false">×</button></header>
      <div class="flex-1 overflow-auto p-4 sm:p-6">
        <div class="grid gap-4 xl:grid-cols-[1fr_1fr]">
          <section class="rounded-2xl border border-white/10 bg-white/5 p-3">
            <h3 class="m-0 text-sm font-black">Issue stock to a boat</h3>
            <div class="mt-3 grid gap-2 sm:grid-cols-2">
              <label class="grid gap-1 text-[11px] font-bold text-slate-300">Stock location<select v-model.number="issue.locationId" class="inventory-input"><option value="">Choose harbour / warehouse</option><option v-for="item in data.locations" :key="item.id" :value="item.id">{{ item.name }}</option></select></label>
              <div class="relative grid gap-1 text-[11px] font-bold text-slate-300">
                <label for="inventory-boat-search">Search boat</label>
                <input id="inventory-boat-search" v-model="issue.boatQuery" class="inventory-input" type="search" inputmode="search" autocomplete="off" placeholder="Type boat name or date…" @focus="boatPickerOpen=true" @input="issue.assignmentId=''" @keydown.escape="boatPickerOpen=false" />
                <div v-if="boatPickerOpen" class="boat-picker">
                  <button v-for="item in filteredAssignments" :key="`${item.boat_id}-${item.service_date}`" type="button" @pointerdown.prevent="selectAssignment(item)" @click.stop="selectAssignment(item)"><span class="min-w-0"><strong class="block truncate text-white">{{ item.boat_name }}</strong><small v-if="item.assigned_users" class="block truncate text-slate-400">{{ item.assigned_users }}</small></span><span>{{ formatAssignmentDate(item.service_date) }}</span></button>
                  <p v-if="!filteredAssignments.length" class="m-0 p-3 text-xs text-slate-500">No boats found.</p>
                </div>
              </div>
            </div>
            <p v-if="selectedAssignment" class="mb-0 mt-2 rounded-xl bg-emerald-400/10 px-3 py-2 text-xs text-emerald-100">Selected: <strong>{{ selectedAssignment.boat_name }}</strong> · {{ formatAssignmentDate(selectedAssignment.service_date) }}</p>
            <div class="mt-3 flex items-center gap-2"><input v-model="productSearch" class="inventory-input" type="search" inputmode="search" placeholder="Search products or boxes…"/><span class="shrink-0 rounded-full bg-emerald-400/15 px-2 py-1 text-[11px] font-black text-emerald-200">{{ selectedProductCount }} selected</span></div>
            <div class="category-tabs mt-2"><button type="button" :class="productCategory==='all'&&'category-tab--active'" @click="productCategory='all'">All</button><button v-for="category in data.categories" :key="category.id" type="button" :class="productCategory===category.id&&'category-tab--active'" @click="productCategory=category.id">{{ category.name }}</button><button type="button" :class="productCategory==='uncategorized'&&'category-tab--active'" @click="productCategory='uncategorized'">Other</button></div>
            <div class="product-picker mt-2">
              <article v-for="product in filteredProducts" :key="product.id" class="product-card" :class="quantityFor(product.id)>0 && 'product-card--selected'">
                <div class="min-w-0 flex-1"><strong class="block truncate text-sm">{{ product.name }}</strong><span class="text-[10px] text-slate-400">{{ product.is_bundle ? bundleDescription(product.id) : product.unit }}</span></div>
                <div class="quantity-stepper"><button type="button" :disabled="quantityFor(product.id)<=0" :aria-label="`Remove one ${product.name}`" @click="changeQuantity(product.id,-1)">−</button><output>{{ formatQuantity(quantityFor(product.id)) }}</output><button type="button" :aria-label="`Add one ${product.name}`" @click="changeQuantity(product.id,1)">+</button></div>
              </article>
              <p v-if="!filteredProducts.length" class="m-0 p-3 text-center text-xs text-slate-500">No products found.</p>
            </div>
            <div class="mt-3 flex items-center gap-3"><span class="min-w-0 flex-1 text-xs text-slate-400">{{ issueSummary }}</span><button type="button" class="shrink-0 rounded-xl bg-emerald-500 px-4 py-2 text-xs font-black disabled:opacity-40" :disabled="!selectedProductCount" @click="submitIssue">Issue & deduct</button></div>
          </section>
          <section class="rounded-2xl border border-white/10 bg-white/5 p-3"><h3 class="m-0 text-sm font-black">Adjust stock</h3><div class="mt-3 grid gap-2 sm:grid-cols-3"><select v-model.number="adjustment.locationId" class="inventory-input"><option value="">Location</option><option v-for="item in data.locations" :key="item.id" :value="item.id">{{ item.name }}</option></select><select v-model.number="adjustment.productId" class="inventory-input"><option value="">Product</option><option v-for="item in data.products" :key="item.id" :value="item.id">{{ item.name }}</option></select><input v-model.number="adjustment.quantityDelta" class="inventory-input" type="number" step="0.01" placeholder="+ received / − used" inputmode="decimal" /></div><button type="button" class="mt-2 w-full rounded-xl bg-sky-500 px-4 py-2 text-xs font-black" @click="saveAdjustment">Save adjustment</button></section>
          <section v-if="bundleProducts.length" class="rounded-2xl border border-violet-300/20 bg-violet-400/[0.05] p-3 xl:col-span-2"><div><span class="text-[10px] font-black uppercase tracking-wider text-violet-300">Stock conversion</span><h3 class="m-0 text-sm font-black">Pack or unpack mixed boxes</h3></div><div class="mt-3 grid gap-2 sm:grid-cols-[1fr_1fr_6rem]"><select v-model.number="conversion.locationId" class="inventory-input"><option value="">Choose location</option><option v-for="item in data.locations" :key="item.id" :value="item.id">{{ item.name }}</option></select><select v-model.number="conversion.bundleProductId" class="inventory-input"><option value="">Choose mixed box</option><option v-for="item in bundleProducts" :key="item.id" :value="item.id">{{ item.name }}</option></select><input v-model.number="conversion.quantity" class="inventory-input" type="number" min="1" step="1" inputmode="numeric" placeholder="Boxes"/></div><p v-if="selectedBundle" class="m-0 mt-2 rounded-xl bg-black/20 px-3 py-2 text-xs text-slate-300">1× {{ selectedBundle.name }} contains {{ bundleDescription(selectedBundle.id) }}</p><div class="mt-2 grid grid-cols-2 gap-2"><button type="button" class="rounded-xl bg-violet-500 px-4 py-2 text-xs font-black" @click="convertBundle('pack')">Pack boxes</button><button type="button" class="rounded-xl bg-white/10 px-4 py-2 text-xs font-black" @click="convertBundle('unpack')">Unpack boxes</button></div></section>
        </div>

        <div v-if="isAdmin && showSettings" class="fixed inset-2 z-[90] flex flex-col overflow-hidden rounded-3xl border border-sky-300/25 bg-slate-950 text-white shadow-2xl sm:inset-5">
          <header class="flex items-center gap-3 border-b border-white/10 px-4 py-3 sm:px-6"><div class="min-w-0 flex-1"><span class="text-[10px] font-black uppercase tracking-wider text-sky-300">Inventory settings</span><h2 class="m-0 truncate text-lg font-black">Locations and product catalogue</h2></div><button type="button" class="rounded-xl bg-white/10 px-3 py-2" aria-label="Close settings" @click="showSettings=false">×</button></header>
          <div class="flex-1 overflow-auto p-4 sm:p-6"><p class="m-0 mb-4 text-xs text-slate-400">These settings are only needed when the stock structure changes.</p><div class="grid gap-4 lg:grid-cols-2">
          <form class="rounded-2xl border border-white/10 p-3" @submit.prevent="createLocation"><h3 class="m-0 text-sm font-black">Add location</h3><div class="mt-2 grid gap-2 sm:grid-cols-[1fr_10rem_auto]"><input v-model.trim="locationForm.name" class="inventory-input" required placeholder="Location name"/><select v-model="locationForm.locationType" class="inventory-input"><option value="harbour">Harbour</option><option value="warehouse">Warehouse</option></select><button class="rounded-xl bg-emerald-500 px-4 text-xs font-black">Add</button></div></form>
          <form class="rounded-2xl border border-white/10 p-3" @submit.prevent="createCategory"><h3 class="m-0 text-sm font-black">Product categories</h3><div class="mt-2 flex gap-2"><input v-model.trim="categoryForm.name" class="inventory-input" required placeholder="New category, e.g. Drinks"/><button class="rounded-xl bg-violet-500 px-4 text-xs font-black">Add</button></div><div class="mt-3 flex flex-wrap gap-2"><span v-for="category in data.categories" :key="category.id" class="flex items-center gap-1 rounded-full bg-violet-400/15 pl-3 text-xs text-violet-100">{{ category.name }}<button type="button" class="min-h-9 min-w-9 rounded-full text-violet-200" :aria-label="`Delete ${category.name}`" @click="deleteCategory(category)">×</button></span><span v-if="!data.categories.length" class="text-xs text-slate-500">No categories yet.</span></div></form>
          <form class="rounded-2xl border border-white/10 p-3" @submit.prevent="createProduct"><h3 class="m-0 text-sm font-black">Add product or bulk box</h3><div class="mt-2 grid gap-2 sm:grid-cols-2"><input v-model.trim="productForm.name" class="inventory-input" required placeholder="Product name"/><select v-model.number="productForm.categoryId" class="inventory-input"><option value="">No category</option><option v-for="category in data.categories" :key="category.id" :value="category.id">{{ category.name }}</option></select><input v-model.trim="productForm.sku" class="inventory-input" placeholder="SKU (optional)"/><input v-model.trim="productForm.unit" class="inventory-input" placeholder="Unit, e.g. can"/></div><label class="mt-3 flex items-center gap-2 text-xs"><input v-model="productForm.bulk" type="checkbox"/> This is a bulk product / box</label><div v-if="productForm.bulk" class="mt-2 grid gap-2"><div v-for="(row,index) in productForm.components" :key="index" class="grid grid-cols-[1fr_6rem_44px] gap-2"><select v-model.number="row.productId" class="inventory-input"><option value="">Contained product</option><option v-for="item in normalProducts" :key="item.id" :value="item.id">{{ item.name }}</option></select><input v-model.number="row.quantity" class="inventory-input" type="number" min="0.01" step="0.01"/><button type="button" class="rounded-xl bg-red-500/15" @click="productForm.components.splice(index,1)">×</button></div><button type="button" class="rounded-xl bg-white/10 px-3 py-2 text-xs" @click="productForm.components.push(emptyLine())">+ Contents</button></div><button class="mt-2 w-full rounded-xl bg-sky-500 px-4 py-2 text-xs font-black">Add product</button></form>
          <section class="rounded-2xl border border-white/10 p-3 lg:col-span-2"><h3 class="m-0 text-sm font-black">Product catalogue</h3><p class="m-0 mt-1 text-xs text-slate-400">Choose the main products shown to crew. Deleted products disappear from active menus while their history remains stored.</p><div class="mt-3 grid gap-2 sm:grid-cols-2"><article v-for="product in data.products" :key="product.id" class="flex flex-wrap items-center gap-2 rounded-xl p-2" :class="product.show_on_boat_menu?'border border-emerald-300/25 bg-emerald-400/[0.07]':'border border-white/10 bg-white/5'"><div class="min-w-0 flex-1"><strong class="block truncate text-xs">{{ product.name }}</strong><span class="text-[10px] text-slate-500">{{ product.is_bundle ? bundleDescription(product.id) : product.unit }}</span></div><button type="button" class="rounded-lg bg-sky-500/15 px-3 py-2 text-xs font-bold text-sky-200" @click="startEditProduct(product)">Edit</button><button type="button" class="rounded-lg px-3 py-2 text-[11px] font-bold" :class="product.show_on_boat_menu?'bg-emerald-500 text-white':'bg-white/10 text-slate-300'" @click="toggleBoatMenuProduct(product)">{{ product.show_on_boat_menu ? 'On boat menu' : 'Hidden' }}</button><button type="button" class="rounded-lg bg-red-500/15 px-3 py-2 text-xs font-bold text-red-200" @click="deleteProduct(product)">Delete</button></article></div></section>
          </div></div>
          <form v-if="editingProduct" class="fixed inset-4 z-[100] flex flex-col overflow-hidden rounded-3xl border border-sky-300/30 bg-slate-950 shadow-2xl sm:inset-10" @submit.prevent="saveEditedProduct"><header class="flex items-center gap-3 border-b border-white/10 px-4 py-3"><div class="min-w-0 flex-1"><span class="text-[10px] font-black uppercase tracking-wider text-sky-300">Edit product</span><h3 class="m-0 truncate text-lg font-black">{{ editingProduct.name }}</h3></div><button type="button" class="rounded-xl bg-white/10 px-3 py-2" @click="editingProduct=null">×</button></header><div class="flex-1 overflow-auto p-4 sm:p-6"><div class="grid gap-3 sm:grid-cols-2"><label class="grid gap-1 text-xs">Name<input v-model.trim="editingProduct.name" class="inventory-input" required/></label><label class="grid gap-1 text-xs">Category<select v-model.number="editingProduct.categoryId" class="inventory-input"><option value="">No category</option><option v-for="category in data.categories" :key="category.id" :value="category.id">{{ category.name }}</option></select></label><label class="grid gap-1 text-xs">SKU<input v-model.trim="editingProduct.sku" class="inventory-input"/></label><label class="grid gap-1 text-xs">Unit<input v-model.trim="editingProduct.unit" class="inventory-input" required/></label></div><label class="mt-4 flex items-center gap-2 text-xs"><input v-model="editingProduct.bulk" type="checkbox"/> This is a bulk product / mixed box</label><div v-if="editingProduct.bulk" class="mt-3 grid gap-2"><div v-for="(row,index) in editingProduct.components" :key="index" class="grid grid-cols-[1fr_6rem_44px] gap-2"><select v-model.number="row.productId" class="inventory-input"><option value="">Contained product</option><option v-for="item in editableComponentProducts" :key="item.id" :value="item.id">{{ item.name }}</option></select><input v-model.number="row.quantity" class="inventory-input" type="number" min="0.01" step="0.01"/><button type="button" class="rounded-xl bg-red-500/15" @click="editingProduct.components.splice(index,1)">×</button></div><button type="button" class="rounded-xl bg-white/10 px-3 py-2 text-xs" @click="editingProduct.components.push(emptyLine())">+ Contents</button></div><p v-if="editorError" class="mt-3 rounded-xl bg-red-500/15 p-3 text-xs text-red-200">{{ editorError }}</p></div><footer class="flex justify-end gap-2 border-t border-white/10 p-3"><button type="button" class="rounded-xl bg-white/10 px-4 py-2 text-xs font-bold" @click="editingProduct=null">Cancel</button><button type="submit" class="rounded-xl bg-sky-500 px-4 py-2 text-xs font-black disabled:opacity-50" :disabled="editorSaving">{{ editorSaving ? 'Saving…' : 'Save product' }}</button></footer></form>
        </div>

        <h3 class="mb-2 mt-5 text-sm font-black">Current stock</h3><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><article v-for="location in data.locations" :key="location.id" class="rounded-2xl border border-white/10 bg-white/5 p-3"><div class="flex justify-between"><strong>{{ location.name }}</strong><span class="text-[10px] uppercase text-emerald-300">{{ location.location_type }}</span></div><div class="mt-2 grid gap-1"><div v-for="row in stockAt(location.id)" :key="row.product_id" class="flex justify-between rounded-lg bg-black/20 px-2 py-2 text-xs"><span>{{ row.product_name }}</span><strong :class="row.quantity <= 0 ? 'text-red-300':'text-white'">{{ formatQuantity(row.quantity) }} {{ row.unit }}</strong></div><p v-if="!stockAt(location.id).length" class="text-xs text-slate-500">No stock recorded.</p></div></article></div>
        <p v-if="message || error" class="mt-3 rounded-xl p-3 text-xs" :class="error?'bg-red-500/15 text-red-200':'bg-emerald-500/15 text-emerald-200'">{{ error || message }}</p>
      </div>
    </section>
  </div>
</template>

<script setup>
import { computed, inject, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
const auth=inject('auth'); const open=ref(false); const showSettings=ref(false); const editingProduct=ref(null); const editorError=ref(''); const editorSaving=ref(false); const error=ref(''); const message=ref(''); const canManage=computed(()=>['admin','harbour'].includes(auth.user?.role)); const isAdmin=computed(()=>auth.user?.role==='admin')
const data=reactive({locations:[],categories:[],products:[],bundleItems:[],stock:[],assignments:[],movements:[]}); const issue=reactive({locationId:'',assignmentId:'',boatQuery:'',lines:[]}); const adjustment=reactive({locationId:'',productId:'',quantityDelta:''}); const conversion=reactive({locationId:'',bundleProductId:'',quantity:1}); const locationForm=reactive({name:'',locationType:'harbour'}); const categoryForm=reactive({name:''}); const productForm=reactive({name:'',sku:'',unit:'piece',categoryId:'',bulk:false,components:[emptyLine()]}); const boatPickerOpen=ref(false); const productSearch=ref(''); const productCategory=ref('all')
const normalProducts=computed(()=>data.products.filter(item=>!item.is_bundle)); const bundleProducts=computed(()=>data.products.filter(item=>item.is_bundle)); const selectedBundle=computed(()=>bundleProducts.value.find(item=>item.id===Number(conversion.bundleProductId))); const selectedAssignment=computed(()=>data.assignments.find(item=>item.id===Number(issue.assignmentId))); const filteredAssignments=computed(()=>{const query=issue.boatQuery.trim().toLocaleLowerCase();return data.assignments.filter(item=>!query||`${item.boat_name} ${item.assigned_users||''} ${item.service_date} ${formatAssignmentDate(item.service_date)}`.toLocaleLowerCase().includes(query)).slice(0,12)}); const filteredProducts=computed(()=>{const query=productSearch.value.trim().toLocaleLowerCase();return data.products.filter(item=>(productCategory.value==='all'||(productCategory.value==='uncategorized'?!item.category_id:item.category_id===productCategory.value))&&(!query||`${item.name} ${item.sku||''} ${item.unit} ${item.category_name||''}`.toLocaleLowerCase().includes(query)))}); const selectedProductCount=computed(()=>issue.lines.filter(line=>line.quantity>0).length); const issueSummary=computed(()=>issue.lines.filter(line=>line.quantity>0).map(line=>`${formatQuantity(line.quantity)}× ${data.products.find(item=>item.id===line.productId)?.name||''}`).join(' · ')||'Choose one or more products')
const editableComponentProducts=computed(()=>data.products.filter(item=>item.id!==editingProduct.value?.id&&!item.is_bundle))
function emptyLine(){return {productId:'',quantity:1}} function stockAt(id){return data.stock.filter(row=>row.location_id===id)} function formatQuantity(value){return Number(value).toLocaleString(undefined,{maximumFractionDigits:2})} function formatAssignmentDate(value){return new Date(`${value}T12:00:00`).toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'})} function selectAssignment(item){issue.assignmentId=item.id;issue.boatQuery=item.boat_name;boatPickerOpen.value=false} function quantityFor(productId){return Number(issue.lines.find(line=>line.productId===productId)?.quantity||0)} function changeQuantity(productId,delta){const line=issue.lines.find(item=>item.productId===productId);const next=Math.max(0,Number(line?.quantity||0)+delta);if(line)line.quantity=next;else if(next>0)issue.lines.push({productId,quantity:next})} function bundleDescription(id){const rows=data.bundleItems.filter(row=>row.bundle_product_id===id);return rows.length?rows.map(row=>`${formatQuantity(row.quantity)}× ${row.component_name}`).join(', '):'Bulk product'}
async function request(url,options={}){const response=await fetch(url,{headers:{'Content-Type':'application/json'},...options});const body=await response.json();if(!response.ok)throw new Error(body.error||'Request failed');return body}
async function load(){try{Object.assign(data,await request('/api/inventory'));error.value=''}catch(e){error.value=e.message}}
async function openPanel(){open.value=true;await load()} async function send(url,body){try{await request(url,{method:'POST',body:JSON.stringify(body)});message.value='Inventory updated.';error.value='';await load();return true}catch(e){error.value=e.message;return false}}
async function createLocation(){await send('/api/inventory/locations',locationForm);locationForm.name=''} async function createCategory(){if(await send('/api/inventory/categories',categoryForm))categoryForm.name=''} async function deleteCategory(category){if(!window.confirm(`Delete category ${category.name}? Its products will become uncategorized.`))return;try{await request(`/api/inventory/categories/${category.id}`,{method:'DELETE'});message.value=`${category.name} deleted.`;await load()}catch(e){error.value=e.message}} async function createProduct(){await send('/api/inventory/products',{...productForm,components:productForm.bulk?productForm.components:[]});Object.assign(productForm,{name:'',sku:'',unit:'piece',categoryId:'',bulk:false,components:[emptyLine()]})}
async function deleteProduct(product){if(!window.confirm(`Delete ${product.name}? Historical movements will be kept.`))return;try{await request(`/api/inventory/products/${product.id}`,{method:'DELETE'});message.value=`${product.name} deleted.`;error.value='';await load()}catch(e){error.value=e.message}}
async function toggleBoatMenuProduct(product){try{await request(`/api/inventory/products/${product.id}/boat-menu`,{method:'PUT',body:JSON.stringify({enabled:!product.show_on_boat_menu})});product.show_on_boat_menu=product.show_on_boat_menu?0:1;message.value='Boat menu selection updated.';error.value=''}catch(e){error.value=e.message}}
function startEditProduct(product){editorError.value='';editingProduct.value={id:product.id,name:product.name,sku:product.sku||'',unit:product.unit,categoryId:product.category_id||'',bulk:Boolean(product.is_bundle),components:data.bundleItems.filter(row=>row.bundle_product_id===product.id).map(row=>({productId:row.component_product_id,quantity:row.quantity}))};if(editingProduct.value.bulk&&!editingProduct.value.components.length)editingProduct.value.components=[emptyLine()]}
async function saveEditedProduct(){const product=editingProduct.value;if(!product||editorSaving.value)return;editorSaving.value=true;editorError.value='';try{await request(`/api/inventory/products/${product.id}`,{method:'PUT',body:JSON.stringify({name:product.name,sku:product.sku,unit:product.unit,categoryId:product.categoryId,components:product.bulk?product.components:[]})});await load();editingProduct.value=null;message.value='Product updated.'}catch(e){editorError.value=e.message}finally{editorSaving.value=false}}
async function saveAdjustment(){if(await send('/api/inventory/adjustments',adjustment))adjustment.quantityDelta=''} async function submitIssue(){if(!issue.assignmentId){error.value='Choose a boat from the search results.';boatPickerOpen.value=true;return}const lines=issue.lines.filter(line=>line.quantity>0);if(!lines.length){error.value='Choose at least one product.';return}if(await send('/api/inventory/issues',{...issue,lines}))issue.lines=[]}
async function convertBundle(direction){if(await send('/api/inventory/conversions',{...conversion,direction}))conversion.quantity=1}
function live(){if(open.value)load()} onMounted(()=>window.addEventListener('inventory-update',live));onBeforeUnmount(()=>window.removeEventListener('inventory-update',live))
</script>
